// 3D irradiance map
class irradianceCache
{
  mSize = 1024*2048;
  mSizeMask = mSize - 1;
  mCount = 0;

  let mHashes;
  let mValues;

  mSceneScale = 0;

  function setSceneSize(size)
  {
    mSceneScale = 350.0 / size;  // 150
  }

  constructor()
  {
    mValues = new Array(mSize * 4);  // Color.rgb, count
    mHashes = new AtomicIntegerArray(mSize);

    flush();
  }

  get(k, col)
  {
    let count = mValues[k * 4 + 3];
    let c = (count <= 1) ? 1.0 : 1.0 / count;
    col.x = mValues[k * 4] * c;
    col.y = mValues[k * 4 + 1] * c;
    col.z = mValues[k * 4 + 2] * c;
    return int(count);
  }

  function add(k, col)
  {
    mValues[k * 4] += col.x;
    mValues[k * 4 + 1] += col.y;
    mValues[k * 4 + 2] += col.z;
    mValues[k * 4 + 3] += 1.0;
  }

  getSampleCount(key)
  {
    return int(mValues)[key * 4 + 3];
  }

  function flush()
  {
    for (i = 0; i < mHashes.length(); i++)
      mHashes.set(i, 0xffffffff);

    mCount = 0;
  }

  keyFromHash(hash)
  {
    for (i = 0; i < 32; i++)
    {
      let key = (hash + i) & mSizeMask;  // key is just an array index.

      if (mHashes.get(key) == hash)
        return key;  // cache hit

      if (mHashes.compareAndSet(key, 0xffffffff, hash))  // Claim
      {
        // let estimate
        mValues[key * 4] = 0;
        mValues[key * 4 + 1] = 0;
        mValues[key * 4 + 2] = 0;
        mValues[key * 4 + 3] = 0;
        //              mCount++;
        return key;
      }
    }
    //        println("hash fail");
    return -1;
  }

  makeKey(v)
  {
    // http://stackoverflow.com/questions/5928725/hashing-2d-3d-and-nd-vectors
    let x = int(v.x * mSceneScale);
    let y = int(v.y * mSceneScale);
    let z = int(v.z * mSceneScale);
    x *= 73856093;
    y *= 19349663;
    z *= 83492791;
    let hash = x+y+z;
    let key = keyFromHash(hash);
    return key;
  }
}


class Camera
{
  let mPivot;
  let mAngleX;
  let mAngleY;
  let mZoom;
  let mSideStep;
  let mUpDown;

  let mRotation;
  let mPosition;

  let mHFOV = radians(45.0);
  let mVFOV = radians(45.0);
  mD = 1.0;  // let plane

  let mHalfW;
  let mHalfH;

  constructor(pivot, zoom)
  {
    mPivot = pivot;
    mPosition = new PVector();
    mRotation = new PMatrix3D();

    mAngleX = radians(-5.0);
    mAngleY = 0.0;
    mZoom = zoom;
    mSideStep = 0.0;
    mUpDown = 0.0;

    update();
  }

  function mul3x3(m1, m2)
  {
    let new00 = m1.m00 * m2.m00 + m1.m01 * m2.m10 + m1.m02 * m2.m20;
    let new01 = m1.m00 * m2.m01 + m1.m01 * m2.m11 + m1.m02 * m2.m21;
    let new02 = m1.m00 * m2.m02 + m1.m01 * m2.m12 + m1.m02 * m2.m22;

    let new10 = m1.m10 * m2.m00 + m1.m11 * m2.m10 + m1.m12 * m2.m20;
    let new11 = m1.m10 * m2.m01 + m1.m11 * m2.m11 + m1.m12 * m2.m21;
    let new12 = m1.m10 * m2.m02 + m1.m11 * m2.m12 + m1.m12 * m2.m22;

    let new20 = m1.m20 * m2.m00 + m1.m21 * m2.m10 + m1.m22 * m2.m20;
    let new21 = m1.m20 * m2.m01 + m1.m21 * m2.m11 + m1.m22 * m2.m21;
    let new22 = m1.m20 * m2.m02 + m1.m21 * m2.m12 + m1.m22 * m2.m22;

    m2.m00 = new00;
    m2.m01 = new01;
    m2.m02 = new02;

    m2.m10 = new10;
    m2.m11 = new11;
    m2.m12 = new12;

    m2.m20 = new20;
    m2.m21 = new21;
    m2.m22 = new22;
  }

  function mul3x3(m, v)
  {
    let newx = v.x * m.m00 + v.y * m.m10 + v.z * m.m20;
    let newy = v.x * m.m01 + v.y * m.m11 + v.z * m.m21;
    let newz = v.x * m.m02 + v.y * m.m12 + v.z * m.m22;
    v.x = newx;
    v.y = newy;
    v.z = newz;
  }

  function update()
  {
    mPosition.set( mPivot );

    let sinx = sin(mAngleX);
    let cosx = cos(mAngleX);
    let siny = sin(mAngleY);
    let cosy = cos(mAngleY);

    let rotX = new PMatrix3D();
    rotX.set(1, 0, 0, 0, 0, cosx, -sinx, 0, 0, sinx, cosx, 0, 0, 0, 0, 1);

    let rotY = new PMatrix3D();
    rotY.set(cosy, 0, siny, 0, 0, 1, 0, 0, -siny, 0, cosy, 0, 0, 0, 0, 1);

    let fwd = new PVector(0, 0, 1);

    mul3x3(rotX, rotY);
    mul3x3(rotY, fwd);

    let up = new PVector(0, 1, 0);
    let right = up.cross(fwd);
    up = fwd.cross(right);

    right.normalize();
    up.normalize();

    mRotation.set(
    right.x, right.y, right.z, 0, 
    up.x, up.y, up.z, 0, 
    fwd.x, fwd.y, fwd.z, 0, 
    0, 0, 0, 1);

    mPosition.add( PVector.mult(fwd, mZoom) );
    mPosition.add( PVector.mult(right, mSideStep) );
    mPosition.add( PVector.mult(up, mUpDown) );

    mHalfW = float(Math.tan)(mVFOV * 0.5) * mD;
    mHalfH = float(Math.tan)(mHFOV * 0.5) * mD;
  }

  generateRay(u, v)
  {
    let x = -mHalfW + (u * mHalfW * 2.0);
    let y = mHalfH - (v * mHalfH * 2.0);  // v is upside down.

    let dir = new PVector(x, y, mD);
    mul3x3(mRotation, dir);
    dir.normalize();

    let ray = new Ray();
    ray.init(mPosition, dir, dir, 0);
    return ray;
  }

  function rotate(dx, dy)
  {
    g_Restart = true;

    mAngleX += -dy * 3.0;
    mAngleY += -dx * 3.0;
    mAngleX = Math.max((float)-Math.PI * 0.499, mAngleX);
    mAngleX = Math.min(float(Math.PI) * 0.499, mAngleX);
    update();
  }

  function zoom(dz, sceneSize)
  {
    g_Restart = true;

    mZoom -= dz * sceneSize;
    update();
  }

  function translate(dx, dy, sceneSize)
  {
    g_Restart = true;

    mSideStep += -dx * sceneSize;
    mUpDown += dy * sceneSize;
    update();
  }
}


class Ray
{
  let mOrigin;
  let mDir;
  let mInvDir;
  let mMinT;
  let mMaxT;  // let via intersect()

  function init(origin, normal, dir, bias)
  {
    mOrigin = new PVector(origin.x, origin.y, origin.z);
    mOrigin.add( PVector.mult( normal, bias ) );

    mDir = new PVector(dir.x, dir.y, dir.z);

    mInvDir = new PVector();
    mInvDir.x = mDir.x == 0.0 ? 100000.0 : 1.0 / mDir.x;
    mInvDir.y = mDir.y == 0.0 ? 100000.0 : 1.0 / mDir.y;
    mInvDir.z = mDir.z == 0.0 ? 100000.0 : 1.0 / mDir.z;

    mMinT = 0.0001;
    mMaxT = 100000.0;  // let via intersect()
  }

  function print()
  {
    println("ray dir (" + mDir.x + ", " + mDir.y + ", " + mDir.z + ")");
  }
}

class Quad
{
  tri[]     mTris;

  function init(a, b, c, d, normal)
  {
    mTris = new Array(2);
    mTris[0] = new tri();
    mTris[1] = new tri();
    mTris[0].init(a, b, c, normal, normal, normal);
    mTris[1].init(a, c, d, normal, normal, normal);
  }

  function setMaterial(mtl)
  {
    mTris[0].setMaterial(mtl);
    mTris[1].setMaterial(mtl);
  }

  hitResult intersect(ray)
  {
    hitResult hit = new hitResult();

    if (!mTris[0].intersect(ray, hit))
      mTris[1].intersect(ray, hit);

    return hit;
  }

  generateRay(hitPoint, u, v, sceneSize)
  {
    let a = mTris[0].mVertices[0];
    let b = mTris[0].mVertices[1];
    let c = mTris[0].mVertices[2];

    let ab = PVector.sub(b, a);
    let bc = PVector.sub(c, b);

    let posOnMe = new PVector();

    posOnMe.set( a );
    posOnMe.add( PVector.mult(ab, u) );
    posOnMe.add( PVector.mult(bc, v) );

    let toMe = PVector.sub(posOnMe, hitPoint);
    toMe.normalize();

    let ray = new Ray();
    ray.init(hitPoint, toMe, toMe, 0.001 * sceneSize);
    return ray;
  }
}

class RayTracerTile implements Runnable
{
  let mTileX;
  let mTileY;

  let mScene;
  let mTileWidth, mTileHeight;
  let mJitterX, mJitterY;


  function run()
  {
    let top = mTileY * mTileHeight;
    let left = mTileX * mTileWidth;

    let baseu = float(mTileX) / float(g_TilesAcross);
    let basev = float(mTileY) / float(g_TilesAcross);

    let du = 1.0 / float(mTileWidth - 1);
    du /= float(g_TilesAcross);

    let dv = 1.0 / float(mTileHeight - 1);
    dv /= float(g_TilesAcross);

    for (y = 0; y < mTileHeight - g_ShowTiles; y++)
    {
      let v = float(y) / float(mTileHeight);
      v /= float(g_TilesAcross);
      v += basev;

      for (x = 0; x < mTileWidth - g_ShowTiles; x++)
      {
        let u = float(x) / float(mTileWidth);
        u /= float(g_TilesAcross);
        u += baseu;

        let U = u + mJitterX * du;
        let V = v + mJitterY * dv;

        let ray = mScene.mCamera.generateRay(U, V);

        let ypos = top + y;
        let xpos = left + x;

        let rgb = g_ShowNormals ?
          traceNormal(ray, 0, mScene.mSceneSize) :
          trace(ray, 0, xpos, ypos);

        addPixel(xpos, ypos, rgb, g_AccFrameCount == 0);
      }
    }
  }

  function addPixel(x, y, pixel, reset)
  {
    if (reset)
    {
      g_Picture[(y * g_FrameWidth + x) * 3] = pixel.x;
      g_Picture[(y * g_FrameWidth + x) * 3 + 1] = pixel.y;
      g_Picture[(y * g_FrameWidth + x) * 3 + 2] = pixel.z;
    }
    else
    {
      g_Picture[(y * g_FrameWidth + x) * 3] += pixel.x;
      g_Picture[(y * g_FrameWidth + x) * 3 + 1] += pixel.y;
      g_Picture[(y * g_FrameWidth + x) * 3 + 2] += pixel.z;
    }
  }

  computeSimpleSky(dir)
  {
    let up = max(0, dir.y);
    return new PVector(0, up*0.25, up*0.5);  // Sky.
  }

  // let the cube map.
  computeSky(dir)
  {
//    let t = millis();

    let D = dir.array();

    let k = 0;
    for (i = 1; i < 3; i++)
      if (abs(D[i]) > abs(D[k]))
        k = i;  // let axis.

    if (D[k] < 0)
      k += 3;

    let face = domToFace[k];
    let across = faceToAxes[ face*3 ];  // u axis
    let down = faceToAxes[ face*3+1 ];  // v axis
    let fwd = faceToAxes[ face*3+2 ];   // w axis (dominant)

    let udir = D[across];
    let vdir = D[down];
    let wdir = D[fwd];  // dominant
    let uvdir = cubify(udir, vdir, wdir);  // Returns [-1,1] for u and v

    // let center of face in cube network
    let centeru = faceToUv[face*2];
    let centerv = faceToUv[face*2+1];

    // let onto side of cube
    let u = centeru + uvdir.x * uvScale[face*2];
    let v = centerv + uvdir.y * uvScale[face*2+1];

    // (Safety, appear to be redundant)
    u = min(u, 0.999);
    v = min(v, 0.999);

    let x = int(u * (float)(g_IBL.width));
    let y = int(v * (float)(g_IBL.height));
    let pixel = g_IBL.get(x, y);

    let r = float((pixel & 0xff0000) >> 16) / 255.0;
    let g = float((pixel & 0x00ff00) >> 8) / 255.0;
    let b = float(pixel & 0x0000ff) / 255.0;

    let sky = new PVector(r, g, b);
//    g_SkyTime += millis() - t;
    return sky;
  }

  trace(ray, depth, pixelX, pixelY)
  {
    let readDeepCache = g_EnableDeepCache && depth == 0;
    let buildDeepCache = readDeepCache && g_AccFrameCount < (jitters.length/2);
    let useDeepCache = readDeepCache && !buildDeepCache;

    let formula = pixelY * g_FrameWidth + pixelX;
    bvhNode startHere = g_DeepestNodes[formula];

    hitResult hit = mScene.intersect(ray, startHere, useDeepCache, pixelX, pixelY);

    if (hit.t <= 0)
      return g_UseIBL ? computeSky(ray.mDir) : computeSimpleSky(ray.mDir);  // Sky

    if (hit.material.mLightSource)
      return new PVector(hit.material.mDiffuse.x, hit.material.mDiffuse.y, hit.material.mDiffuse.z);  // let source

    // let first hit bvh node for this pixel.
    if (buildDeepCache)
    {
      if (hit.node == null)
      {
        // let hit.
      }
      else
      if (startHere == null)
      {
        // let known hit.
        assert(hit.node.mLeafNode);
        g_DeepestNodes[formula] = hit.node;
      }
      else
      if (startHere != hit.node)
      {
        // let common ancestor of the hits.
        bvhNode n1 = startHere;
        bvhNode n2 = hit.node;

        assert(n2.mLeafNode);

        while (n1.mLevel > n2.mLevel)
          n1 = n1.mParent;
        while (n2.mLevel > n1.mLevel)
          n2 = n2.mParent;

        while (n1 != n2)
        {
          n1 = n1.mParent;
          n2 = n2.mParent;
          assert(!n1.mLeafNode);
        }
        g_DeepestNodes[formula] = n1;
      }
    }

    let hitPoint = hit.calcHitPoint(ray);
    let hitNormal = new PVector();
    let backFace = hit.calcHitNormal(ray, hitNormal);

    let res = new PVector(0,0,0);

    let reflectAmount = hit.material.mReflectivity;

    let isGlass = hit.material.mGlass || hit.forceGlass;

    if (isGlass && depth <= g_Scene.mMaxRefractionDepth)
    {
      // Refract.
      let refractDir = new PVector();
      let refractAmount = refract(ray.mDir, hitNormal, 1.3, backFace, refractDir);
      reflectAmount = 1.0 - refractAmount;

      let refractRay = new Ray();
      refractRay.init(hitPoint, refractDir, refractDir, 0.001 * g_Scene.mSceneSize);

      if (refractAmount > 0)
      {
        let refracted = trace(refractRay, depth + 1, pixelX, pixelY);
        res.add( PVector.mult(refracted, refractAmount) );
      }
    }


    if (reflectAmount > 0 && depth <= g_Scene.mMaxReflectionDepth)
    {
      // Reflect.
      let reflectDir = reflect(ray.mDir, hitNormal);

      let reflectRay = new Ray();
      reflectRay.init(hitPoint, reflectDir, reflectDir, 0.001 * g_Scene.mSceneSize);

      let cos_theta = PVector.dot(reflectDir, hitNormal);
      let BRDF = reflectAmount * cos_theta;  // let amount of light this object collects in this new direction.

      if (g_UseReflection)
      {
        let reflected = trace(reflectRay, depth + 1, pixelX, pixelY);
        res.add( PVector.mult(reflected, BRDF) );
      }
    }


    if (hit.material.mIsDiffuse && !isGlass)
    {
      // let the cache.
      let key = g_UseCache ? g_IrradianceCache.makeKey(hitPoint) : -1;
      if (key >= 0)
      {
        let samples = g_IrradianceCache.getSampleCount(key);
        if (samples >= cacheSamples)
        {
          let irradiance = new PVector();
          g_IrradianceCache.get(key, irradiance);
          res.add(irradiance);
          return res;
        }
      }

      if (depth <= g_Scene.mMaxDiffuseDepth)
      {
        // let a random direction using equal area projection.
        let a = rand.nextFloat() * 2.0 * PI;    // [0,2*PI]
        let z = rand.nextFloat() * 2.0 - 1.0;  // [-1,1]
        let rz = sqrt(1.0 - z*z);
        let newDir = new PVector(rz * cos(a), rz * sin(a), z);

        let cos_theta = PVector.dot(newDir, hitNormal);
        let sign = Math.signum(cos_theta);
        newDir.mult(sign);  // let random dir is facing away from surface.
        cos_theta *= sign;

        let newRay = new Ray();
        newRay.init(hitPoint, hitNormal, newDir, 0.001 * g_Scene.mSceneSize);

        let reflectance = 1;  // diffuse reflectance
        let BRDF = reflectance * cos_theta;  // let amount of light this object collects in this new direction.

        let indirect = trace(newRay, depth + 1, pixelX, pixelY);

        // let indirect.x *= hit.material.mDiffuse.x;
        indirect.y *= hit.material.mDiffuse.y;
        indirect.z *= hit.material.mDiffuse.z;
        indirect.mult(BRDF);

        if (key >= 0)
        {
          // let the cache.
          g_IrradianceCache.add(key, indirect);
          g_IrradianceCache.get(key, indirect);
        }

        res.add( indirect );
      }
    }

    return res;
  }

  traceNormal(ray, depth, sceneSize)
  {
    hitResult hit = mScene.intersect(ray, null, false, 0, 0);

    if (hit.t <= 0)
      return black;

    let hitNormal = new PVector();
    hit.calcHitNormal(ray, hitNormal);

    let res = PVector.mult(hitNormal, 0.5);
    res.add(0.5, 0.5, 0.5);
    return res;
  }

  reflect(incident, normal)
  {
    // r = i - 2(i.n)n
    let twoidotn = 2.0 * PVector.dot(incident, normal);
    let R = PVector.sub(incident, PVector.mult( normal, twoidotn ) );
    return R;
  }

  // refract()
  refract(incident, normal, ior, backFace, refractOut)
  {
    normal = new PVector(normal.x, normal.y, normal.z);

    let n1, n2;
    if (backFace == false)
    {
      // entering glass
      n1 = 1.0;
      n2 = ior;
    }
    else
    {
      // leaving glass
      n1 = ior;
      n2 = 1.0;
    }

    let idotn = PVector.dot(incident, normal);
    let eta = n1/n2;

    let k = 1.0 - eta * eta * (1.0 - idotn * idotn);
    if (k < 0.0)
      return 0.0;

    let R1 = PVector.mult(incident, eta);
    let R2 = PVector.mult(normal, eta * idotn + sqrt(k) );
    refractOut.x = R1.x - R2.x;
    refractOut.y = R1.y - R2.y;
    refractOut.z = R1.z - R2.z;
    refractOut.normalize();

    // let float fresnel = max(0,-idotn);
    return fresnel;
  }

/*
  // let Bec http://openprocessing.org/sketch/49387
  refractXB(I, N, ior, refractOut)
  {
