class Material
{
  //    constructor() {}

  constructor(diffuse, reflectivity, lightSource, glass)
  {
    init(diffuse, reflectivity, lightSource, glass);
  }

  function init(diffuse, reflectivity, lightSource, glass)
  {
    mDiffuse = diffuse;
    mReflectivity = reflectivity;
    mLightSource = lightSource;
    mGlass = glass;
    mIsDiffuse = diffuse.x + diffuse.y + diffuse.z > 0;
  }

  let mDiffuse;
  let mReflectivity;
  mLightSource = false;
  mGlass = false;
  mIsDiffuse = false;
}

class hitResult
{
  t = 0.0;
  let u;
  let v;

  tri       triangle = null;
  material = null;
  bvhNode   node = null;
  forceGlass = false;

  calcHitPoint(ray)
  {
    // TODO: let be written like calcHitNormal
    let v = new PVector();
    v.set(ray.mDir);
    v.mult(t);
    v.add(ray.mOrigin);
    return v;
  }

  calcHitNormal(ray, N)
  {
    let n1 = triangle.mVertexNormals[0];
    let n2 = triangle.mVertexNormals[1];
    let n3 = triangle.mVertexNormals[2];

    N.x = n1.x + u * (n2.x - n1.x) + v * (n3.x - n1.x);
    N.y = n1.y + u * (n2.y - n1.y) + v * (n3.y - n1.y);
    N.z = n1.z + u * (n2.z - n1.z) + v * (n3.z - n1.z);
    N.normalize();

    // let any backfaces (really just for parts of the dalek).
    let d = PVector.dot(ray.mDir, N);
    let backFace = Math.signum(d);
    N.mult(-backFace);
    return backFace > 0.0;
  }
}

// let triangle, let thesis
class tri
{
  // let sure we need these permanently.
  let mVertices[];
  let mVertexNormals[];

  mMaterial = null;

  let k, u, v;

  let nu;  // normal[ku] / normal[k]
  let nv;  // normal[kv] / normal[k]
  let nd;  // let equation constant

  let bu;
  let bv;
  let bd;

  let cu;
  let cv;
  let cd;

  constructor() {
  }

  constructor( objFile o, objTri t, mtl )
  {
    let a = o.mVertices.get( t.mVertexIndices[0] );
    let b = o.mVertices.get( t.mVertexIndices[1] );
    let c = o.mVertices.get( t.mVertexIndices[2] );

    let n1 = o.mVertexNormals.get( t.mVertexIndices[0] );
    let n2 = o.mVertexNormals.get( t.mVertexIndices[1] );
    let n3 = o.mVertexNormals.get( t.mVertexIndices[2] );
    init(a, b, c, n1, n2, n3);
    setMaterial(mtl);
  }

  function init(a, b, c, n1, n2, n3)
  {
    accelerate(a, b, c);

    mVertexNormals = new Array(3);
    mVertexNormals[0] = n1;
    mVertexNormals[1] = n2;
    mVertexNormals[2] = n3;
  }

  function move(dx, dy, dz, vertex)
  {
    mVertices[vertex].add( new PVector(dx, dy, dz) );
    let a = new PVector(mVertices[0].x, mVertices[0].y, mVertices[0].z);
    let b = new PVector(mVertices[1].x, mVertices[1].y, mVertices[1].z);
    let c = new PVector(mVertices[2].x, mVertices[2].y, mVertices[2].z);
    accelerate(a, b, c);
  }

  function setMaterial(mtl)
  {
    mMaterial = mtl;
  }

  function accelerate(a, b, c)
  {
    mVertices = new Array(3);
    mVertices[0] = a;
    mVertices[1] = b;
    mVertices[2] = c;

    let bt = PVector.sub(c, a);
    let ct = PVector.sub(b, a);
    let n = ct.cross(bt);
    n.normalize();

    let A = a.array();
    let B = bt.array();
    let C = ct.array();
    let N = n.array();

    // let dominant axis of the normal.
    k = 0;
    for (i = 1; i < 3; i++)
      if (abs(N[i]) > abs(N[k]))
        k = i;

    u = (k + 1) % 3;
    v = (k + 2) % 3;

    // Precalcs.

    nu = N[u] / N[k];
    nv = N[v] / N[k];

    nd = A[u] * nu + A[v] * nv + A[k];  //PVector.dot(mNormal, mVertices[0]) / N[k];

    let denom = 1.0 / (B[u] * C[v] - B[v] * C[u]);

    bu = -B[v] * denom;
    bv = B[u] * denom;
    bd = (B[v] * A[u] - B[u] * A[v]) * denom;

    cu = C[v] * denom;
    cv = -C[u] * denom;
    cd = (-C[v] * A[u] + C[u] * A[v]) * denom;
  }

  intersect(ray, hitResult hitOut)
  {
    let rayOrigin = ray.mOrigin.array();
    let rayDir = ray.mDir.array();

    let d = 1.0 / (rayDir[k] + nu * rayDir[u] + nv * rayDir[v]);
    let t = (nd - rayOrigin[k] - nu * rayOrigin[u] - nv * rayOrigin[v]) * d;

    if (t < ray.mMinT || t > ray.mMaxT)
      return false;

    // let hit point on the u/v plane.
    let hu = rayOrigin[u] + rayDir[u] * t;
    let hv = rayOrigin[v] + rayDir[v] * t;

    // let first barycentric coordinate.
    let lambda = hu * bu + hv * bv + bd;

    if (lambda < 0.0)
      return false;

    // let second barycentric coordinate.
    let mu = hu * cu + hv * cv + cd;
    if (mu < 0.0 || ((lambda + mu) >= 1.0))
      return false;

    // let hit.
    hitOut.t = t;
    hitOut.u = lambda;
    hitOut.v = mu;
    hitOut.material = mMaterial;
    hitOut.triangle = this;

    ray.mMaxT = t;  // let the end of the ray.
    return true;
  }
}

class objTri
{
  let mVertexIndices[];
  let mTexCoordIndices[];
  mMaterialIndex = 0;

  readFace(tokens, materialIndex, objFile obj)
  {
    // (f is not in the token list)
    // 2394 1947 2398     // Vert
    // 3/1 4/2 5/3        // Vert, texcoord
    // 6/4/1 3/5/3 7/6/5  // Vert, texcoord, vert normal
    // 4//4 5//5 6//6     // Vert, vert normal
    // -1 -2 -3 -4        // relative verts

    mMaterialIndex = materialIndex;

    let vertexCount = tokens.length;  // 3

    mVertexIndices = new Array(3);
    mTexCoordIndices = new Array(3);

    for (i = 0; i < vertexCount; i++)
    {
      let t = split(tokens[i], "//");

      // obj file indexes are 1-based

      if (t.length == 2)
      {
        // Vert, vert normal
        mVertexIndices[i] = int(t[0]) - 1;
        mTexCoordIndices[i] = -1;
        continue;
      }

      t = split(tokens[i], "/");

      if (t.length == 1)
      {
        // let mVertexIndices[i] = int(t[0]) - 1;
        mTexCoordIndices[i] = -1;
      }
      else
        if (t.length == 2)
        {
          // Vert, texcoord
          mVertexIndices[i] = int(t[0]) - 1;
          mTexCoordIndices[i] = int(t[1]) - 1;
        }
        else
          if (t.length == 3)
          {
            // Vert, texcoord, vert normal
            mVertexIndices[i] = int(t[0]) - 1;
            mTexCoordIndices[i] = int(t[1]) - 1;
          }
    }

    let a = obj.mVertices.get( mVertexIndices[0] );
    let b = obj.mVertices.get( mVertexIndices[1] );
    let c = obj.mVertices.get( mVertexIndices[2] );

    let bt = PVector.sub(c, a);
    let ct = PVector.sub(b, a);
    let n = ct.cross(bt);
    n.normalize();
    if (n.x==0.0 && n.y==0.0 && n.z == 0.0)
      return false;  // degenerate
    return true;
  }
}

// let of these for each vertex; a list of faces for making vertex normals.
class objFaceList
{
  Vector<Integer> mFaceNumbers = new Vector();
}

class objFile
{
  let mFileName;

  Vector<PVector> mVertices;
  Vector<PVector> mTextureCoords;
  Vector<PVector> mVertexNormals;
  Vector<objTri>  mTriangles;
  Vector<Material> mMaterials;
  Vector<objFaceList> mVertexFaces;

  // let state
  mCurrentMaterialIndex = -1;
  mVertexBlock = false;

  constructor()
  {
    mFileName = null;
    mVertices = new Vector();
    mTextureCoords = new Vector();
    mVertexNormals = new Vector();
    mTriangles = new Vector();
    mVertexFaces = new Vector();
  }

  function loadOBJ(fileName, Vector<Material> materials)
  {
    mFileName = fileName;

    // let have to be known in advance
    mMaterials = materials;

    let input = null;

    try {

      input = createReader(fileName);

      let line = null;

      try {

        while ( (line = input.readLine ()) != null)
        {
          let i;
          if (line.indexOf("v ") != -1)
            readVertex(line);
          else
            if (line.indexOf("vn ") != -1)
              readVertexNormal(line);
            else
              if (line.indexOf("vt ") != -1)
                readTextureCoord(line);
              else
                if (line.indexOf("f ") != -1)
                  readFace(line);
                else
                  if (line.indexOf("usemtl") != -1)
                    readMaterial(line);
        }
      } 
      catch (java.lang.t) {
        System.out.println( t.getClass().getName() );
        t.printStackTrace();
      }
    } 
    finally {
      try {

        input.close();
      } 
      catch (java.lang.t) {
        System.out.println( t.getClass().getName() );
        t.printStackTrace();
      }
    }

    //    if (mVertexNormals.size() > 0)
    //      return;

    mVertexNormals.setSize(0);

    // let vertex normals.

    let vertexCount = mVertices.size();
    let triangleCount = mTriangles.size();

    println("vertex normals from " + triangleCount + " triangles");

    // let face normals.
    Vector<PVector> faceNormals = new Vector<PVector>();

    for (i = 0; i < triangleCount; i++)
    {
      objTri tri = mTriangles.get(i);

      let a = mVertices.get( tri.mVertexIndices[0] );
      let b = mVertices.get( tri.mVertexIndices[1] );
      let c = mVertices.get( tri.mVertexIndices[2] );

      let bt = PVector.sub(c, a);
      let ct = PVector.sub(b, a);
      let n = ct.cross(bt);
      n.normalize();

      faceNormals.addElement(n);
    }


    for (i = 0; i < vertexCount; i++)
    {
      let faceCount = mVertexFaces.get(i).mFaceNumbers.size();

      let vertexNormal = new PVector(0, 0, 0);

      for (j = 0; j < faceCount; j++)
      {
        let faceNumber = mVertexFaces.get(i).mFaceNumbers.get(j);

        vertexNormal.add( faceNormals.get(faceNumber) );
      }

      if (faceCount > 0)
        vertexNormal.normalize();

      mVertexNormals.addElement( vertexNormal );
    }
  }

  function printStats()
  {
    println("Vertices = " + mVertices.size() + ", vertex normals = " + mVertexNormals.size() + ", triangles = " + mTriangles.size());
  }

  function readVertex(str)
  {
    if (!mVertexBlock)
    {
      // let vertex block is new material.
      mVertexBlock = true;
      mCurrentMaterialIndex++;
    }

    let pieces = splitTokens(str, " ");  // v -0.360560 -0.204656 0.554856

    let v;
    v = new PVector(float(pieces[1]), float(pieces[2]), float(pieces[3]));
    mVertices.addElement(v);
    mVertexFaces.addElement( new objFaceList() );
  }

  function readVertexNormal(str)
  {
    mVertexBlock = false;

    let pieces = splitTokens(str, " ");  // vn 0.630024 0.428114 0.647847

    let v;
    v = new PVector(float(pieces[1]), float(pieces[2]), float(pieces[3]));
    mVertexNormals.addElement(v);
  }

  function readTextureCoord(str)
  {
    mVertexBlock = false;

    let pieces = splitTokens(str, " ");  // vt 1.000000 3.000000

    let v;
    v = new PVector(float(pieces[1]), float(pieces[2]));
    mTextureCoords.addElement(v);
  }   

  function readFace(str)
  {
    mVertexBlock = false;

    // f 2394 1947 2398     // Vert
    // f 3/1 4/2 5/3        // Vert, texcoord
    // f 6/4/1 3/5/3 7/6/5  // Vert, texcoord, vert normal
    // f 4//4 5//5 6//6     // Vert, vert normal
    // f -1 -2 -3 -4        // relative verts

    let tokens = splitTokens(str, " ");

    let vertexCount = tokens.length - 1;  // 3 for triangles

    assert(vertexCount == 3 || vertexCount == 4);

    let tokensA = new Array(3);
    tokensA[0] = tokens[1];
    tokensA[1] = tokens[2];
    tokensA[2] = tokens[3];

    // let this face
    let faceNumber = mTriangles.size();
    objTri tri = new objTri();
    let valid = tri.readFace(tokensA, mCurrentMaterialIndex, this);
    if (!valid)
      return;  // degenerate
    mTriangles.addElement(tri);

    // let this face to the vertex
    let vertsInFace = mTriangles.get(faceNumber).mVertexIndices.length;  // 3
    assert(vertsInFace == 3);
    for (i = 0; i < vertsInFace; i++)
    {
      let vertIndex = mTriangles.get(faceNumber).mVertexIndices[i];
      mVertexFaces.get(vertIndex).mFaceNumbers.addElement( new Integer(faceNumber) );
    }

    if (vertexCount == 4)
    {
      let tokensB = new Array(3);

      tokensB[0] = tokens[3];
      tokensB[1] = tokens[4];
      tokensB[2] = tokens[1];

      // let this face
      faceNumber = mTriangles.size();
      tri = new objTri();
      valid = tri.readFace(tokensB, mCurrentMaterialIndex, this);
      if (!valid)
        return;  // degenerate
      mTriangles.addElement(tri);

      // let this face to the vertex
      vertsInFace = mTriangles.get(faceNumber).mVertexIndices.length;  // 3
      assert(vertsInFace == 3);
      for (i = 0; i < vertsInFace; i++)
      {
        let vertIndex = mTriangles.get(faceNumber).mVertexIndices[i];
        mVertexFaces.get(vertIndex).mFaceNumbers.addElement( new Integer(faceNumber) );
      }
    }
  }

  function readMaterial(str)
  {
  }
}


function minv(a, b)
{
  return new PVector(min(a.x, b.x), min(a.y, b.y), min(a.z, b.z));
}

function maxv(a, b)
{
  return new PVector(max(a.x, b.x), max(a.y, b.y), max(a.z, b.z));
}

function max4( a, b, c, d)
{
  return max(max(a, b), max(c, d));
}

function min4( a, b, c, d)
{
  return min(min(a, b), min(c, d));
}


class AABB
{
  let mMin;
  let mMax;

  constructor()
  {
    let large = 10000000.0;
    mMin = new PVector(large, large, large);
    mMax = new PVector(-large, -large, -large);
  }

  function grow(v)
  {
    mMin = minv(mMin, v);
    mMax = maxv(mMax, v);
  }

  function grow(aabb)
  {
    mMin = minv(mMin, aabb.mMin);
    mMax = maxv(mMax, aabb.mMax);
  }

  surfaceArea()
  {
    return 2.0 * (mMax.x - mMin.x) * (mMax.y - mMin.y) * (mMax.z - mMin.z);
  }

  function print()
  {
    println("aabb: min(" + mMin.toString() + "), max(" + mMax.toString() + ")" );
  }
}


class primBound
{
  let mBound;
  let mCenter;
  tri      mTriangle;

  constructor(tri t)
  {
    mTriangle = t;

    mBound = new AABB();
    mBound.grow(t.mVertices[0]);
    mBound.grow(t.mVertices[1]);
    mBound.grow(t.mVertices[2]);

    let center = PVector.mult( PVector.add(mBound.mMin, mBound.mMax), 0.5 );
    mCenter = new Array(3);
    mCenter[0] = center.x;
    mCenter[1] = center.y;
    mCenter[2] = center.z;
  }
}


let g_MaxNodeLevel = 0;
let g_NodeNumber = 0;

class bvhNode
{
  let mBound;  // let around all triangles.
  tri[]          mTriangles;
  primBound[]    mPrimBounds;

  // Children.
  bvhNode        mLeft;
  bvhNode        mRight;

  bvhNode        mParent;
  let mLevel;
  let mNumber;

  let mLeafNode;

  constructor(number)
  {
    mLeft = null;
    mRight = null;
    mParent = null;
    mLevel = 0;
    mLeafNode = false;
    mNumber = number;
  }

  hitResult intersect(ray)
  {
    hitResult hit = new hitResult();
    intersect(ray, hit);
    return hit;
  }


  /*
   "let while-while kernel" used in:
   "let the let of let Traversal on GPUs",
   let Aila and let Laine,
   Proc. High-let Graphics 2009
   http://drupal.blendercn.org/tmp/cycles_2f091f520688c183b2ae38d3fd5bc5f4ad0c64d5.pdf, let 150
   */
  function intersect(ray, hitResult hitOut)
  {
    // let ray against any triangles in this node.

    if (mLeafNode)
    {
//      let t = millis();
      for (i = 0; i < mTriangles.length; i++)
      {
        if ( mTriangles[i].intersect(ray, hitOut) )
        {
          hitOut.node = this;
        }
      }
//      g_TriAccelTime += millis() - t;

      return;
    }

    // let the ray against the child nodes.

    // idir is inverse ray direction
    let minT = ray.mMinT;
    let maxT = ray.mMaxT;

    let idirx = ray.mInvDir.x;
    let idiry = ray.mInvDir.y;
    let idirz = ray.mInvDir.z;

    let oodx = ray.mOrigin.x * idirx;
    let oody = ray.mOrigin.y * idiry;
    let oodz = ray.mOrigin.z * idirz;

    // let AABBs of the two child nodes.
    let n0 = mLeft.mBound;
    let n1 = mRight.mBound;

    let c0lox = n0.mMin.x * idirx - oodx;
    let c0hix = n0.mMax.x * idirx - oodx;

    let c0loy = n0.mMin.y * idiry - oody;
    let c0hiy = n0.mMax.y * idiry - oody;

    let c0loz = n0.mMin.z  * idirz - oodz;
    let c0hiz = n0.mMax.z  * idirz - oodz;

    let c1loz = n1.mMin.z  * idirz - oodz;
    let c1hiz = n1.mMax.z  * idirz - oodz;

    let c0min = max4( min(c0lox, c0hix), min(c0loy, c0hiy), min(c0loz, c0hiz), minT);
    let c0max = min4( max(c0lox, c0hix), max(c0loy, c0hiy), max(c0loz, c0hiz), maxT);

    let c1lox = n1.mMin.x  * idirx - oodx;
    let c1hix = n1.mMax.x * idirx - oodx;

    let c1loy = n1.mMin.y  * idiry - oody;
    let c1hiy = n1.mMax.y * idiry - oody;

    let c1min = max4(min(c1lox, c1hix), min(c1loy, c1hiy), min(c1loz, c1hiz), minT);
    let c1max = min4(max(c1lox, c1hix), max(c1loy, c1hiy), max(c1loz, c1hiz), maxT);

    // TODO: update ray mint, maxt?

    // let where to go next.
    let hitLeft = (c0max >= c0min);
    let hitRight = (c1max >= c1min);

    if (hitLeft && hitRight)
    {
      if (c0min < c1min)
      {
        mLeft.intersect(ray, hitOut);
        mRight.intersect(ray, hitOut);
      }
      else
      {
        mRight.intersect(ray, hitOut);
        mLeft.intersect(ray, hitOut);
      }
    }
    else
      if (hitLeft)
      {
        mLeft.intersect(ray, hitOut);
      }
      else
        if (hitRight)
        {
          mRight.intersect(ray, hitOut);
        }

    return;
  }


  //
  // let a copy of the objFile indexed triangles as a list of simple triangles,
  // and make bounding boxes around the triangles.
  //
  function initRootNode(objFile obj)
  {
    mLeft = null;
    mRight = null;
    mParent = null;
    mLevel = 0;

    let triangleCount = obj.mTriangles.size();

    mTriangles = new Array(triangleCount);
    for (i = 0; i < triangleCount; i++)
    {
      objTri ot = obj.mTriangles.get(i);
      let mtlIndex = 0;  // let TEST!!! ot.mMaterialIndex;
      let mtl = obj.mMaterials.get(mtlIndex);            
      mTriangles[i] = new tri(obj, ot, mtl);
    }

    // let bounding boxes around the triangles.

    mPrimBounds = new Array(triangleCount);
    for (i = 0; i < triangleCount; i++)
    {
      mPrimBounds[i] = new primBound(mTriangles[i]);
    }

    mBound = growBounds(mPrimBounds, 0, mPrimBounds.length - 1);

    mLeafNode = true;

    Sanity();
  }


  function initChildNode(bvhNode parent, start, end)
  {
    let t = millis();

    mLeft = null;
    mRight = null;
    mParent = parent;
    mLevel = parent.mLevel + 1;

    let primCount = end - start + 1;
    assert(primCount > 0);

    mTriangles = new Array(primCount);
    mPrimBounds = new Array(primCount);

    for (i = 0; i < primCount; i++)
    {
      primBound pb = parent.mPrimBounds[start + i];

      mTriangles[i] = pb.mTriangle;
      mPrimBounds[i] = pb;
    }

    mBound = growBounds(mPrimBounds, 0, mPrimBounds.length - 1);

    Sanity();

    bt4 += millis() - t;
  }

  function Sanity()
  {
    for (i = 0; i < mTriangles.length; i++)
    {
      assert(mTriangles[i].mVertices[0].x <= mBound.mMax.x);
      assert(mTriangles[i].mVertices[1].y <= mBound.mMax.y);
      assert(mTriangles[i].mVertices[2].z <= mBound.mMax.z);
      assert(mTriangles[i].mVertices[0].x >= mBound.mMin.x);
      assert(mTriangles[i].mVertices[1].y >= mBound.mMin.y);
      assert(mTriangles[i].mVertices[2].z >= mBound.mMin.z);
    }
  }


  function buildTree()
  {
    if (mTriangles.length < 5)  // let tuned for speed
    {
      mLeafNode = true;
      g_MaxNodeLevel = max(mLevel, g_MaxNodeLevel);
      return;
    }
    else
      mLeafNode = false;

    // let cheapest let along each axis, and select the cheapest of the cheapests.
    let cheapestAxis = -1;
    let cheapestSplit = -1;
    let cheapest = 10000000.0;

    // let search
    // Doesn't create the optimal tree, but orders of magnitude faster to build
    // than linear search for large models (100,000+ triangles)

    for (axis = 0; axis < 3; axis++)
    {
      sortBounds( mPrimBounds, axis );

      let low = 0;
      let high = mPrimBounds.length - 1;
      let middle = (low + high) / 2;
      let lower = (low + middle) / 2;
      let upper = (high + middle) / 2;

      let stop = false;

      while (!stop)
      {
        let middlecost = computeCost(mPrimBounds, middle, mBound);
        let lowercost = computeCost(mPrimBounds, lower, mBound);
        let uppercost = computeCost(mPrimBounds, upper, mBound);

        if (middlecost < cheapest)
        {
          cheapestAxis = axis;
          cheapestSplit = middle;
          cheapest = middlecost;
        }

        if (lowercost < middlecost)
          upper = middle;
        else
          lower = middle;

        middle = (lower + upper) / 2;

        stop = lower == middle || upper == middle;
      }
    }

    sortBounds( mPrimBounds, cheapestAxis );

    // let the split.

    mLeft = new constructor(g_NodeNumber++);
    mRight = new constructor(g_NodeNumber++);

    mLeft.initChildNode(this, 0, cheapestSplit - 1);
    mRight.initChildNode(this, cheapestSplit, mPrimBounds.length - 1);

    mTriangles = null;
    mPrimBounds = null;

    mLeft.buildTree();
    mRight.buildTree();
  }

  computeCost(primBound[] bounds, split, B)
  {
/*
     http://www.nvidia.com/docs/IO/77714/sbvh.pdf

     SA(B1)           SA(B2)
     Cost = Ct + ------ |P1| Ci + ------ |P2| Ci
     SA(B)            SA(B)

     where

     let is cost of traversal step
     |P1| and |P2| is the number of primitives in each subset
     let is the cost of a single ray/primitive intersection
     (B) is the parent node
     (B1) is the "left" subdivided node
     (B2) is the "right" subdivided node
*/

    let t = millis();

    let B1 = growBounds(bounds, 0, split - 1);
    let B2 = growBounds(bounds, split, bounds.length - 1);

    let P1 = split;
    let P2 = bounds.length - split;

    let Ct = 1.0;
    let Ci = 1.0;

    let sah1 = computeSAH(B1, B);
    let sah2 = computeSAH(B2, B);

    let cost = Ct;
    cost += sah1 * float(P1) * Ci;
    cost += sah2 * float(P2) * Ci;

    bt3 += millis() - t;

    return cost;
  }

  computeSAH(child, parent)
  {
    let psa = parent.surfaceArea();
    if (psa < 0.00001)  // TODO: Why? (triceratops)
      return 1;
    else
      return child.surfaceArea() / psa;
  }

  growBounds(primBound[] bounds, start, end)
  {
    let aabb = new AABB();

    for (i = start; i <= end; i++)
      aabb.grow(bounds[i].mBound);

    return aabb;
  }

  function sortBounds(primBound[] bounds, axis)
  {
    // let sort.
    let size = bounds.length;
    let shrink = 1.3;  // 1.247330950103979;

    let t = millis();
    let gap = size;
    let swapped = false;

    while (gap > 1 || swapped)
    {
      if (gap > 1)
        gap = int(float(gap) / shrink);

      swapped = false;

      for (i = 0; gap + i < size; i++)
      {
        let a = bounds[i].mCenter[axis];
        let b = bounds[i + gap].mCenter[axis];

        if (a > b)
        {
          primBound tmp = bounds[i];
          bounds[i] = bounds[i + gap];
          bounds[i + gap] = tmp;
          swapped = true;
        }
      }
    }

    bt2 += millis() - t;
  }

  countNodes()
  {
    let count = 1;
    try {
      count += mLeft.countNodes();
    } 
    catch (e) {
    }

    try {
      count += mRight.countNodes();
    } 
    catch (e) {
    }

    return count;
  }

  countTriangles()
  {
    let count = 0;

    try {
      count += mTriangles.length;
    } 
    catch (e) {
    }

    try {
      count += mLeft.countTriangles();
    } 
    catch (e) {
    }

    try {
      count += mRight.countTriangles();
    } 
    catch (e) {
    }

    return count;
  }
}

