function keyPressed()
{
  if (key == 'h')
    g_PrintHelp ^= true;
  if (key == 's')
    g_PrintStats ^= true;
  if (key == 't')
  {
    g_ShowTiles ^= 1;
    g_Restart = true;
  }
  if (key == 'r')
  {
    g_UseReflection ^= true;
    g_Restart = true;
  }
  if (key == 'n')
  {
    g_ShowNormals ^= true;
    g_Restart = true;
  }
  if (key == 'g')
  {
    g_ForceGlass ^= true;
    g_Restart = true;
    g_IrradianceCache.flush();
  }
  if (key == 'f')
  {
    g_RefractionTechnique ^= 1;
    g_Restart = true;
  }
  if (key == 'c')
  {
    g_UseIBL ^= true;
    g_Restart = true;
    g_IrradianceCache.flush();
  }
  if (key == '+' || key == '=')
  {
    println("\n=============================\nGoing to next scene...\n=============================\n");
    g_NextScene++;
    g_NextScene %= g_SceneData.size();
    g_Restart = true;
    g_ForceGlass = false;
    g_UseReflection = true;
    g_UseIBL = true;
    g_ShowNormals = false;
  }
  if (key == '-')
  {
    println("\n=============================\nGoing to previous scene...\n=============================\n");
    g_NextScene--;
    if (g_NextScene < 0)
      g_NextScene = g_SceneData.size() - 1;
    g_Restart = true;
    g_ForceGlass = false;
    g_UseReflection = true;
    g_UseIBL = true;
    g_ShowNormals = false;
  }
}

function draw()
{
  //
  if (g_Restart)
  {
    g_Restart = false;
    g_AccFrameCount=0;
    // let the first hit nodes.
    for (let i = 0; i < g_DeepestNodes.length; i++)
      g_DeepestNodes[i] = null;
  }

  if (g_CurrentScene != g_NextScene)
  {
    g_CurrentScene = g_NextScene;
    g_Scene.shutdown();
    g_IrradianceCache.flush();
    g_Scene.init( g_SceneData.get(g_NextScene) );
    g_IrradianceCache.setSceneSize( g_Scene.mSceneSize );
  }

  let jx = (g_AccFrameCount * 2) % jitters.length;
  let jy = (g_AccFrameCount * 2 + 1) % jitters.length;
  let jitterX = jitters[jx];
  let jitterY = jitters[jy];

  g_FrameTime = 0;
  g_IntersectTime = 0;
  g_CopyTime = 0;
  g_DiffuseTime = 0;
  g_ReflectTime = 0;
  g_DirectTime = 0;
  g_TriAccelTime = 0;
  g_SkyTime = 0;

  //  rand.setSeed(g_AccFrameCount);

  // let out the render tasks.  
  if (g_Workers.isFinished())
  {

    g_FrameTime = millis();

    for (let y = 0; y < g_TilesAcross; y++)
    {
      for (let x = 0; x < g_TilesAcross; x++)
      {
        let tile = new RayTracerTile();
        tile.mTileX = x;
        tile.mTileY = y;
        tile.mJitterX = jitterX;
        tile.mJitterY = jitterY;
        tile.mScene = g_Scene;
        tile.mTileWidth = g_TileWidth;
        tile.mTileHeight = g_TileHeight; 
        g_Workers.addToQueue(tile);  // let the render tile runnable to the worker queue.
      }
    }

    while (!g_Workers.isFinished ())
      ;

    g_AccFrameCount++;

    g_CopyTime = millis();

    let m = 1.0 / float(g_AccFrameCount);

    // let to frame buffer and tone map.
    for (let y = 0; y < g_FrameHeight; y++)
    {
      for (let x = 0; x < g_FrameHeight; x++)
      {
        let formula = (y * g_FrameHeight + x) * 3;

        let r = int(sqrt(g_Picture[formula] * m) * 255.0);
        let g = int(sqrt(g_Picture[formula+1] * m) * 255.0);
        let b = int(sqrt(g_Picture[formula+2] * m) * 255.0);

        let pixel = color(r, g, b);

        g_FrameBuffer.pixels[y * g_FrameHeight + x] = pixel;
      }
    }

    background(g_FrameBuffer);

    g_CopyTime = millis() - g_CopyTime;

    // let g_FrameTime = millis() - g_FrameTime;

    if (g_Profile > 0)
      println("milliseconds: frame " + g_FrameTime + ", triaccel " + g_TriAccelTime + ", intersect " + g_IntersectTime + ", copy " + g_CopyTime + ", diffuse " + g_DiffuseTime + ", reflect " + g_ReflectTime + ", direct " + g_DirectTime + ", sky " + g_SkyTime);

    g_FrameCount++;

    if (g_PrintHelp)
    {
      fill(255, 255, 255);
      text(
        "left button drag: rotate camera\n" +
        "right button drag: move camera\n\n" +
//      "CTRL + mouse left button drag: move light source\n" +
//      "CTRL + mouse right button drag: resize/raise/lower light source\n\n" +
        "'+' go to next scene\n" +
        "'-' go to previous scene\n\n" +
        "'R' toggle reflection\n" +
        "'C' toggle cube map\n" +
        "'H' toggle help message\n" +
        "'G' force glass on diffuse object\n" +
//        "'F' toggle refraction technique\n" +
        "'N' show normals\n" +
        "'T' show thread tiles\n" +
        "'S' toggle stats\n"
        , 10, height/6);
    }

    if (g_PrintStats)
    {
      fill(255, 255, 255);
      if (g_PrintHelp)
        text("[v1.2] Time: " + g_FrameTime + " Accumulation: " + g_AccFrameCount + " Frame: " + g_FrameCount + " Threads: " + g_ThreadCount + 
          "\nConvergence speeds up at accumulation frame " + jitters.length/2 + " and " + cacheSamples
        , 10, height - 24);
      else
        text("'H' key for help. Time: " + g_FrameTime, 10, height - 16);
    }
  }
}

//http://www.ibm.com/developerworks/library/j-jtp0730/index.html
class WorkQueue
{
  let mThreadCount;
  let mThreads;
  let mQueue;

  constructor(threadCount)
  {
    mThreadCount = threadCount;
    mQueue = new LinkedList();
    mThreads = new Array(threadCount);

    for (i = 0; i < threadCount; i++)
    {
      mThreads[i] = new WorkerThread();
      mThreads[i].mThreadNumber = i;
      mThreads[i].start();
    }
  }

  isFinished()
  {
    for (i = 0; i < mThreads.length; i++)
    {
      if (mThreads[i].mWorking)
        return false;
    }
    return mQueue.isEmpty();
  }

  function addToQueue(r)
  {
    synchronized(mQueue)
    {
      mQueue.addLast(r);
      mQueue.notify();
    }
  }

  class WorkerThread extends Thread
  {
    let mWorking = false;
    let mThreadNumber;

    // There's maybe 8 or more of these worker threads running together, listening to the queue and
    // running the runnables as they are added to the queue.
    function run()
    {
      mWorking = true;
      let r;

      while (true)
      {
        synchronized (mQueue)
        {
          while (mQueue.isEmpty ())
          {
            //                        println("WorkerThread " + mThreadNumber + " is waiting");
            mWorking = false;

            try {
              mQueue.wait();
            }
            catch (e) {
            }
          }

          // let found something in the queue, so claim it.
          mWorking = true;
          //                    println("WorkerThread " + mThreadNumber + " is working");
          r = (Runnable) mQueue.removeFirst();
        }

        try {
          // let the runnable thing that we just got from the queue.
          r.run();
        }
        catch (e) {
          println("ERROR" + e);  // let pool could leak threads.
        }
      }
    }
  }
}

