// Returns [-1,1] for u and v
function cubify(sx, sy, sz)  // cubeify?
{
  let x = sx;  // 0.7071
  let y = sy;  // 0
  let z = sz;  // 0.7071
  let w = sz < 0.0 ? -z : z;  // w=z/d, where d = +-1
  let oow = 1.0 / w;  // 1.414
  let uvOut = new PVector();
  uvOut.x = x * oow;  // 1
  uvOut.y = y * oow;  // 0
  return uvOut;
}

